const tz = 'Europe/Lisbon';
const now = $now.setZone(tz);
return [{ json: {
  date: now.toFormat('yyyy-MM-dd'),
  dayName: now.toFormat('cccc, d LLLL yyyy'),
  tz,
  vaultFolder: '/vault/Daily',
  city: 'Guimarães', lat: 41.4425, lon: -8.2918,
  ollamaUrl: 'http://host.docker.internal:11434',
  model: 'qwen3.5:9b',
  googleMcpUrl: 'http://mcp-google:8000/mcp',
  githubRepos: ['your-user/your-repo'],
  hoursBack: 24,
  itemsPerFeed: 4,
  feeds: {
    'Local AI': [
      'https://github.com/ollama/ollama/releases.atom',
      'https://huggingface.co/blog/feed.xml',
    ],
    'Cybersecurity': [
      'https://www.bleepingcomputer.com/feed/',
      'https://feeds.feedburner.com/TheHackersNews',
    ],
    'Tech': [
      'https://feeds.arstechnica.com/arstechnica/index',
      'https://www.theverge.com/rss/index.xml',
    ],
    'CS2 / Esports': [
      'https://www.hltv.org/rss/news',
    ],
  },
  sections: {},
}}];

const fs = require('fs');
const path = require('path');
const s = $input.first().json;
const file = path.join(s.vaultFolder, `${s.date} Briefing.md`);
let manual = false;
try { manual = $('Test run').isExecuted; } catch (e) { manual = false; }
if (!manual) {
  if (fs.existsSync(file)) return [];
  if ($now.setZone(s.tz).hour < 6) return [];
}
return [{ json: { ...s, file, manual } }];

const s = $input.first().json;
const codes = {0:'clear sky',1:'mainly clear',2:'partly cloudy',3:'overcast',45:'fog',48:'fog',
  51:'light drizzle',53:'drizzle',55:'heavy drizzle',61:'light rain',63:'rain',65:'heavy rain',
  66:'freezing rain',67:'freezing rain',71:'light snow',73:'snow',75:'heavy snow',80:'rain showers',
  81:'rain showers',82:'violent rain showers',95:'thunderstorm',96:'thunderstorm with hail',99:'thunderstorm with hail'};
try {
  const url = 'https://api.open-meteo.com/v1/forecast'
    + `?latitude=${s.lat}&longitude=${s.lon}`
    + '&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max,wind_speed_10m_max'
    + `&timezone=${encodeURIComponent(s.tz)}&forecast_days=1`;
  const r = await this.helpers.httpRequest({ url, json: true });
  const d = r.daily;
  s.sections.weather = {
    text: `${s.city}: ${codes[d.weather_code[0]] ?? 'code ' + d.weather_code[0]}, `
      + `${Math.round(d.temperature_2m_min[0])}–${Math.round(d.temperature_2m_max[0])} °C, `
      + `rain chance ${d.precipitation_probability_max[0]}%, wind up to ${Math.round(d.wind_speed_10m_max[0])} km/h`,
  };
} catch (e) {
  s.sections.weather = { error: e.message };
}
return [{ json: s }];

const s = $input.first().json;
const since = Date.now() - s.hoursBack * 3600 * 1000;
const decode = (t) => (t || '')
  .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1')
  .replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
  .replace(/&#39;|&apos;/g, "'").replace(/&#(\d+);/g, (m, n) => String.fromCharCode(n))
  .replace(/&amp;/g, '&')
  .replace(/<[^>]+>/g, ' ')
  .replace(/\s+/g, ' ').trim();
const tag = (block, name) => {
  const m = block.match(new RegExp(`<${name}[^>]*>([\\s\\S]*?)</${name}>`, 'i'));
  return m ? m[1] : '';
};
const news = {}; const errors = [];
for (const [category, urls] of Object.entries(s.feeds)) {
  news[category] = [];
  for (const url of urls) {
    try {
      let xml = await this.helpers.httpRequest({ url, json: false,
        headers: { 'User-Agent': 'Mozilla/5.0 (local daily briefing)' } });
      if (typeof xml !== 'string') xml = Buffer.isBuffer(xml) ? xml.toString('utf8') : String(xml);
      const blocks = xml.match(/<item[\s>][\s\S]*?<\/item>|<entry[\s>][\s\S]*?<\/entry>/gi) || [];
      const source = decode(tag(xml.split(/<item|<entry/i)[0], 'title')) || new URL(url).hostname;
      let count = 0;
      for (const b of blocks) {
        if (count >= s.itemsPerFeed) break;
        const title = decode(tag(b, 'title'));
        let link = decode(tag(b, 'link'));
        if (!link) { const m = b.match(/<link[^>]*href="([^"]+)"/i); link = m ? m[1] : ''; }
        const dateStr = decode(tag(b, 'pubDate') || tag(b, 'published') || tag(b, 'updated') || tag(b, 'dc:date'));
        const t = Date.parse(dateStr);
        if (!isNaN(t) && t < since) continue;
        const summary = decode(tag(b, 'description') || tag(b, 'summary') || tag(b, 'content')).slice(0, 300);
        if (title && link) { news[category].push({ title, link, source, summary }); count++; }
      }
    } catch (e) {
      errors.push(`${url}: ${e.message}`);
    }
  }
}
s.sections.news = { items: news, errors };
return [{ json: s }];

const s = $input.first().json;
const token = $env.GITHUB_TOKEN;
const since = new Date(Date.now() - s.hoursBack * 3600 * 1000).toISOString();
const headers = { 'Accept': 'application/vnd.github+json', 'User-Agent': 'local-daily-briefing',
  'X-GitHub-Api-Version': '2022-11-28' };
if (token) headers['Authorization'] = `Bearer ${token}`;
const repos = [];
for (const repo of s.githubRepos) {
  const r = { repo, issues: [], prs: [], commits: [] };
  try {
    const issues = await this.helpers.httpRequest({ url: `https://api.github.com/repos/${repo}/issues?state=open&per_page=30`, headers, json: true });
    for (const i of issues) {
      const entry = { number: i.number, title: i.title, url: i.html_url };
      (i.pull_request ? r.prs : r.issues).push(entry);
    }
    const commits = await this.helpers.httpRequest({ url: `https://api.github.com/repos/${repo}/commits?since=${since}&per_page=10`, headers, json: true });
    r.commits = commits.map(c => ({ sha: c.sha.slice(0, 7), message: c.commit.message.split('\n')[0], url: c.html_url }));
  } catch (e) {
    r.error = e.message + (token ? '' : ' (no GITHUB_TOKEN set)');
  }
  repos.push(r);
}
s.sections.github = repos;
return [{ json: s }];

const s = $input.first().json;
const url = s.googleMcpUrl;
const email = $env.USER_GOOGLE_EMAIL;
const helpers = this.helpers;
let sid = null; let nextId = 0;

const parse = (body) => {
  if (Buffer.isBuffer(body)) body = body.toString('utf8');
  if (typeof body !== 'string') return body || {};
  const t = body.trim();
  if (t.startsWith('{')) return JSON.parse(t);
  const datas = t.split('\n').filter(l => l.startsWith('data:')).map(l => l.slice(5).trim());
  for (const d of datas.reverse()) { try { const j = JSON.parse(d); if (j.result || j.error) return j; } catch (e) {} }
  return {};
};
async function rpc(method, params, notify = false) {
  const headers = { 'Content-Type': 'application/json', 'Accept': 'application/json, text/event-stream' };
  if (sid) headers['mcp-session-id'] = sid;
  const msg = notify ? { jsonrpc: '2.0', method, params } : { jsonrpc: '2.0', id: ++nextId, method, params };
  const res = await helpers.httpRequest({ method: 'POST', url, headers, body: JSON.stringify(msg),
    json: false, returnFullResponse: true, ignoreHttpStatusErrors: true });
  const h = res.headers || {};
  sid = sid || h['mcp-session-id'] || h['Mcp-Session-Id'];
  if (notify) return null;
  const j = parse(res.body);
  if (j.error) throw new Error(j.error.message || JSON.stringify(j.error));
  return j.result;
}
const textOf = (result) => (result?.content || []).map(c => c.text || '').join('\n').trim();

const out = {};
try {
  await rpc('initialize', { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'n8n-briefing', version: '1' } });
  await rpc('notifications/initialized', {}, true);
  const tools = ((await rpc('tools/list', {}))?.tools || []).map(t => t.name);
  const start = $now.setZone(s.tz).startOf('day');
  const calls = {
    calendar: ['get_events', { user_google_email: email, calendar_id: 'primary',
      time_min: start.toISO(), time_max: start.plus({ days: 1 }).toISO(), max_results: 20 }],
    tasks: ['list_tasks', { user_google_email: email, task_list_id: '@default', show_completed: false, max_results: 20 }],
    email: ['search_gmail_messages', { user_google_email: email,
      query: 'is:unread newer_than:2d -category:promotions -category:social -category:updates', page_size: 10 }],
  };
  for (const [key, [name, args]] of Object.entries(calls)) {
    if (!tools.includes(name)) { out[key] = { error: `tool ${name} not found (available: ${tools.join(', ')})` }; continue; }
    try {
      const r = await rpc('tools/call', { name, arguments: args });
      const text = textOf(r).slice(0, 4000);
      if (/ACTION REQUIRED|Authentication Needed/i.test(text)) out[key] = { error: 'Google sign-in needed (see README: Google sign-in link)' };
      else if (r?.isError) out[key] = { error: text.slice(0, 300) };
      else out[key] = { text };
    } catch (e) { out[key] = { error: e.message }; }
  }
} catch (e) {
  out.error = `Google server not reachable: ${e.message}`;
}
s.sections.google = out;
return [{ json: s }];

const s = $input.first().json;
const g = s.sections.google || {};
const a = s.sections.app || {};
const part = (o) => o?.text ? o.text : (o?.error ? `[unavailable: ${o.error}]` : '[no data]');
const newsLines = Object.entries(s.sections.news?.items || {})
  .map(([cat, items]) => `## ${cat}\n` + (items.length ? items.map(i => `- ${i.title} (${i.source}): ${i.summary}`).join('\n') : '- nothing new'))
  .join('\n');
const gh = (s.sections.github || []).map(r => `${r.repo}: ${r.issues.length} open issues, ${r.prs.length} open PRs, `
  + `${r.commits.length} new commits${r.commits.length ? ' (' + r.commits.map(c => c.message).join('; ') + ')' : ''}`).join('\n');

const prompt = `Today is ${s.dayName}. Write my daily briefing in English, in Markdown, using ONLY the data below.
Never invent events, tasks, emails, news or numbers. If a part says unavailable or no data, say so in one short line.
Copy facts exactly: keep the same words for weather ("light rain" stays "light rain", never "heavy"), counts and names.
Keep each news item under the category it is listed in (for example, security stories are Security, not Tech).

Output exactly these two sections:
### Highlights
3 to 5 short bullets, each starting with its category in bold (**Weather**, **Calendar**, **Tasks**, **Email**, **GitHub**, **CI**, **Security**, **Politics**, **Markets**, **Local AI**, **Tech**, **CS2**, **YouTube**): the most important things for my day.
Only include things that actually happened or are coming up. NEVER write a highlight that just says there is nothing (no "no events", "no tasks", "nothing important"). A failed CI run or a newly exploited (KEV) bug affecting my software comes first.
### Today
**Calendar:** bullets with time and title (or "No events").
**Tasks:** bullets (or "No open tasks").
**Email:** bullets "Sender – Subject" for messages that look personal or important; skip newsletters (or "Nothing important").

DATA
[Weather] ${s.sections.weather?.text || 'unavailable'}
[Calendar]
${part(g.calendar)}
[Tasks]
${part(g.tasks)}
[Unread email]
${part(g.email)}
[GitHub]
${gh || 'no data'}
[News]
${newsLines}
[CI runs] ${(a.ci || []).map(w => `${w.repo} ${w.name}@${w.branch}: ${w.result}`).join('; ') || 'no data'}
[Newly exploited vulnerabilities (CISA KEV)] ${(a.kev || []).map(k => `${k.id} ${k.what}${k.ransomware ? ' (ransomware)' : ''}`).join('; ') || 'none'}
[New CVEs in software I use] ${(a.watch || []).map(x => `${x.id} CVSS ${x.cvss ?? '?'} (${x.watch.join('/')})${x.kev ? ' KEV' : ''}`).join('; ') || 'none'}
[Markets] ${(a.markets || []).join(', ') || 'no data'}
[Politics] ${(a.politics || []).map(p => `${p.region}: ${p.text.replace(/\n/g, ' ')}`).join(' | ').slice(0, 3000) || 'no data'}
[New YouTube videos] ${(a.youtube || []).map(v => `${v.channel}: ${v.title} (${v.verdict})`).join('; ') || 'none'}`;

try {
  const r = await this.helpers.httpRequest({ method: 'POST', url: `${s.ollamaUrl}/api/chat`, json: true, timeout: 300000,
    body: { model: s.model, stream: false, think: false, keep_alive: '2m',
      options: { num_ctx: 16384, temperature: 0.2 },
      messages: [{ role: 'user', content: prompt }] } });
  s.summary = (r.message?.content || '').trim();
} catch (e) {
  s.summary = `_Summary unavailable (Ollama: ${e.message})._`;
}
return [{ json: s }];

const fs = require('fs');
const s = $input.first().json;
const L = [];
L.push('---', `date: ${s.date}`, 'tags: [briefing]', '---', '', `# Briefing · ${s.dayName}`, '');
L.push(`**Weather:** ${s.sections.weather?.text || '_unavailable_'}`, '');
L.push(s.summary || '', '');

L.push('### GitHub');
for (const r of s.sections.github || []) {
  L.push(`**[${r.repo}](https://github.com/${r.repo})**`);
  if (r.error) { L.push(`- _unavailable: ${r.error}_`); continue; }
  L.push(`- Open issues (${r.issues.length}): ` + (r.issues.slice(0, 8).map(i => `[#${i.number} ${i.title}](${i.url})`).join(', ') || 'none'));
  L.push(`- Open PRs (${r.prs.length}): ` + (r.prs.map(p => `[#${p.number} ${p.title}](${p.url})`).join(', ') || 'none'));
  L.push(`- New commits (${r.commits.length}): ` + (r.commits.map(c => `[${c.sha}](${c.url}) ${c.message}`).join('; ') || 'none'));
}
L.push('');

const A = s.sections.app || {};
if ((A.ci || []).length) {
  L.push('### CI');
  for (const w of A.ci) L.push(`- ${w.result === 'success' ? '✅' : w.result === 'failure' ? '❌' : '⏳'} ${w.repo} · ${w.name} @ ${w.branch}: [${w.result}](${w.url})`);
  L.push('');
}
if ((A.kev || []).length || (A.watch || []).length) {
  L.push('### Threat intel');
  for (const k of A.kev || []) L.push(`- **KEV** [${k.id}](https://nvd.nist.gov/vuln/detail/${k.id}) ${k.what}${k.ransomware ? ' · ransomware' : ''}`);
  for (const x of A.watch || []) L.push(`- **Your stack** [${x.id}](https://nvd.nist.gov/vuln/detail/${x.id}) CVSS ${x.cvss ?? '?'} · ${x.watch.join(', ')}${x.kev ? ' · KEV' : ''}`);
  L.push('');
}
if ((A.markets || []).length || A.marketNews) {
  L.push('### Markets');
  if ((A.markets || []).length) L.push(A.markets.join(' · '), '');
  if (A.marketNews) L.push(A.marketNews, '');
  L.push('<small>Delayed quotes · not investment advice</small>', '');
}
if ((A.politics || []).length) {
  L.push('### Politics');
  for (const p of A.politics) L.push(`**${p.region}**`, p.text, '');
}
if ((A.youtube || []).length) {
  L.push('### YouTube');
  for (const v of A.youtube) L.push(`- [${v.title}](${v.link}) · ${v.channel} · _${v.verdict}${v.why ? ': ' + v.why : ''}_`);
  L.push('');
}
L.push('### News');
for (const [cat, items] of Object.entries(s.sections.news?.items || {})) {
  L.push(`**${cat}**`);
  if (!items.length) L.push('- nothing new');
  for (const i of items) L.push(`- [${i.title}](${i.link}) · ${i.source}`);
  L.push('');
}
if (s.sections.news?.errors?.length) L.push(`<small>Feeds that failed: ${s.sections.news.errors.join(' | ')}</small>`, '');

L.push('---', `_Generated ${$now.setZone(s.tz).toFormat('HH:mm')} by n8n + ${s.model}. Links come straight from the sources._`);

fs.mkdirSync(s.vaultFolder, { recursive: true });
fs.writeFileSync(s.file, L.join('\n'), 'utf8');
return [{ json: { written: s.file.replace('/vault', 'Vault'), date: s.date } }];

const fs = require('fs');
const s = $input.first().json;
const read = (f) => { try { return JSON.parse(fs.readFileSync(`/home/node/.n8n/${f}`, 'utf8')); } catch (e) { return null; } };
const day = 864e5, now = Date.now();
const news = read('mailapp-news.json'), vul = read('mailapp-vulns.json'), yt = read('mailapp-youtube.json'), gh = read('mailapp-github.json');
const app = {};
if (news?.markets?.length) app.markets = news.markets.filter(m => !m.error && m.change != null)
  .map(m => `${m.name} ${m.change >= 0 ? '▲' : '▼'}${Math.abs(m.change).toFixed(2)}%`);
if (news?.summaries) {
  app.politics = Object.entries(news.summaries).filter(([k]) => k.startsWith('Politics/')).map(([k, v]) => ({ region: k.split('/')[1], text: v.text }));
  if (news.summaries.Markets) app.marketNews = news.summaries.Markets.text;
}
if (vul) {
  const since = new Date(now - 2 * day).toISOString().slice(0, 10);
  app.kev = (vul.kev || []).filter(k => k.added >= since).map(k => ({ id: k.id, what: `${k.vendor} ${k.product} – ${k.name}`, ransomware: k.ransomware }));
  app.watch = Object.values(vul.cves || {}).filter(x => x.watch?.length && Date.parse(x.published) >= now - day).map(x => ({ id: x.id, cvss: x.cvss, watch: x.watch, kev: x.kev }));
}
if (gh?.repos) app.ci = gh.repos.flatMap(r => (r.health || []).map(w => ({ repo: r.repo, name: w.name, branch: w.branch, result: w.status !== 'completed' ? w.status : w.conclusion, url: w.url })));
if (yt?.videos) app.youtube = yt.videos.filter(v => v.t >= now - day && v.verdict !== 'skip').map(v => ({ title: v.title, channel: v.channel, link: v.link, verdict: v.verdict, why: v.why }));
s.sections.app = app;
return [{ json: s }];
